package policy; import core.*;import java.util.Map; public final class LocalPolicyParser{public PolicyDocument parseIni(String text){PolicyDocument doc=new PolicyDocument();Map<String,Map<String,String>> ini=IniUtil.parse(text);for(Map.Entry<String,Map<String,String>> e:ini.entrySet()){FirewallRule r=new FirewallRule();r.chain(e.getKey().toUpperCase());Map<String,String> m=e.getValue();if(m.containsKey("action"))r.action(m.get("action").toUpperCase());if(m.containsKey("protocol"))r.protocol(m.get("protocol"));if(m.containsKey("source"))r.source(m.get("source"));if(m.containsKey("destination"))r.destination(m.get("destination"));if(m.containsKey("dport"))r.destinationPort(PortRange.parse(m.get("dport")));doc.add(r);}return doc;}public FirewallRule parseJsonRule(String line){Map<String,String> m=JsonLite.parseFlatObject(line);FirewallRule r=new FirewallRule();if(m.containsKey("chain"))r.chain(m.get("chain").toUpperCase());if(m.containsKey("action"))r.action(m.get("action").toUpperCase());if(m.containsKey("protocol"))r.protocol(m.get("protocol"));if(m.containsKey("source"))r.source(m.get("source"));if(m.containsKey("destination"))r.destination(m.get("destination"));if(m.containsKey("dport"))r.destinationPort(PortRange.parse(m.get("dport")));return r;}}
